 1	// Dafny verification of binary search alogirthm from binary_search.py
 2	// Inspired by: https://ece.uwaterloo.ca/~agurfink/stqam/rise4fun-Dafny/#h211
 3	
 4	method BinarySearch(arr: array<int>, target: int) returns (index: int)
 5	    requires distinct(arr)
 6	    requires sorted(arr)
 7	    ensures -1 <= index < arr.Length
 8	    ensures index == -1 ==> not_found(arr, target)
 9	    ensures index != -1 ==> found(arr, target, index)
10	{
11	    var low, high := 0 , arr.Length-1;
12	    while low <= high
13	        invariant 0 <= low <= high + 1
14	        invariant forall i :: 0 <= i <= low && high <= i < arr.Length ==> arr[i] != target
15	    { 
16	        var mid := (low + high) / 2;
17	        if arr[mid] == target
18	        {
19	           return mid;
20	        }
21	        else if arr[mid] < target
22	        {
23	           low := mid + 1;
24	        }
25	        else
26	        {
27	           high := mid - 1;
28	        }
29	    }
30	
31	    return -1;
32	}
33	
34	// Predicate to check that the array is sorted
35	predicate sorted(a: array<int>)
36	reads a
37	{
38	   forall j, k :: 0 <= j < k < a.Length ==> a[j] <= a[k] 
39	}
40	
41	// Predicate to that each element is unique
42	predicate distinct(arr: array<int>)
43	    reads arr
44	{
45	    forall i, j :: 0 <= i < arr.Length && 0 <= j < arr.Length ==> arr[i] != arr[j]
46	}
47	
48	// Predicate to that the target is not in the array
49	predicate not_found(arr: array<int>, target: int)
50	reads arr
51	{
52	    (forall j :: 0 <= j < arr.Length ==> arr[j] != target)
53	}
54	
55	// Predicate to that the target is in the array
56	predicate found(arr: array<int>, target: int, index: int)
57	requires -1 <= index < arr.Length;
58	reads arr
59	{
60	    if index == -1 then false
61	    else if arr[index] == target then true
62	    else false
63	}
64	
65	
66

